def __str__(self) -> str:
    """Render the line."""
    if not self:
        return '\n'

    indent = '    ' * self.depth
    leaves = iter(self.leaves)
    first = next(leaves)
    res = f'{first.prefix}{indent}{first.value}'
    for leaf in leaves:
        res += str(leaf)
    for comment in self.comments.values():
        res += str(comment)
    return res + '\n'

