def has_excessive_failures(self):
    if self.failures.first_failure_time is not None:
        if (time.time() >= self.failures.first_failure_time +
                self.disable_hard_timeout):
            return True

    if self.failures.num_failures() >= self.disable_failures:
        return True

    return False

