                if hasattr(o, "dtypes") and o.ndim > 1:
                    s = o.dtypes.value_counts()
                    if len(s) > 1:
                        return False
                    dtypes |= set(s.index.astype(str))

                elif hasattr(o, "dtype"):
                    dtypes |= {o.dtype.name}


