                        embed_webpage if age_gate else video_webpage,
                        'JS player URL (1)', default=None)
                    if not jsplayer_url_json and not age_gate:
                        # We need the embed website after all
                        if embed_webpage is None:
                            embed_url = proto + '://www.youtube.com/embed/%s' % video_id
                            embed_webpage = self._download_webpage(
                                embed_url, video_id, 'Downloading embed webpage')
                        jsplayer_url_json = self._search_regex(
                            ASSETS_RE, embed_webpage, 'JS player URL')

                    player_url = json.loads(jsplayer_url_json)
                    if player_url is None:
                        player_url_json = self._search_regex(
                            r'ytplayer\.config.*?"url"\s*:\s*("[^"]+")',
                            video_webpage, 'age gate player URL')
                        player_url = json.loads(player_url_json)

                if 'sig' in url_data:
                    url += '&signature=' + url_data['sig'][0]
                elif 's' in url_data:
                    encrypted_sig = url_data['s'][0]

                    if self._downloader.params.get('verbose'):
                        if player_url is None:
                            player_desc = 'unknown'
                        else:
                            player_type, player_version = self._extract_player_info(player_url)
                            player_desc = '%s player %s' % ('flash' if player_type == 'swf' else 'html5', player_version)
                        parts_sizes = self._signature_cache_id(encrypted_sig)
                        self.to_screen('{%s} signature length %s, %s' %
                                       (format_id, parts_sizes, player_desc))

                    signature = self._decrypt_signature(
                        encrypted_sig, video_id, player_url, age_gate)
                    sp = try_get(url_data, lambda x: x['sp'][0], compat_str) or 'signature'
                    url += '&%s=%s' % (sp, signature)
            if 'ratebypass' not in url:
                url += '&ratebypass=yes'

            dct = {
                'format_id': format_id,
                'url': url,
                'player_url': player_url,
            }
            if format_id in self._formats:
                dct.update(self._formats[format_id])
            if format_id in formats_spec:
                dct.update(formats_spec[format_id])

            # Some itags are not included in DASH manifest thus corresponding formats will
            # lack metadata (see https://github.com/ytdl-org/youtube-dl/pull/5993).
            # Trying to extract metadata from url_encoded_fmt_stream_map entry.
            mobj = re.search(r'^(?P<width>\d+)[xX](?P<height>\d+)$', url_data.get('size', [''])[0])
            width, height = (int(mobj.group('width')), int(mobj.group('height'))) if mobj else (None, None)

            if width is None:
                width = int_or_none(fmt.get('width'))
            if height is None:
                height = int_or_none(fmt.get('height'))

            filesize = int_or_none(url_data.get(
                'clen', [None])[0]) or _extract_filesize(url)

            quality = url_data.get('quality', [None])[0] or fmt.get('quality')
            quality_label = url_data.get('quality_label', [None])[0] or fmt.get('qualityLabel')

            tbr = (float_or_none(url_data.get('bitrate', [None])[0], 1000)
                   or float_or_none(fmt.get('bitrate'), 1000)) if format_id != '43' else None
            fps = int_or_none(url_data.get('fps', [None])[0]) or int_or_none(fmt.get('fps'))

            more_fields = {
                'filesize': filesize,
                'tbr': tbr,
                'width': width,
                'height': height,
                'fps': fps,
                'format_note': quality_label or quality,
            }
            for key, value in more_fields.items():
                if value:
                    dct[key] = value
            type_ = url_data.get('type', [None])[0] or fmt.get('mimeType')
            if type_:
                type_split = type_.split(';')
                kind_ext = type_split[0].split('/')
                if len(kind_ext) == 2:
                    kind, _ = kind_ext
                    dct['ext'] = mimetype2ext(type_split[0])
                    if kind in ('audio', 'video'):
                        codecs = None
                        for mobj in re.finditer(
                                r'(?P<key>[a-zA-Z_-]+)=(?P<quote>["\']?)(?P<val>.+?)(?P=quote)(?:;|$)', type_):
                            if mobj.group('key') == 'codecs':
                                codecs = mobj.group('val')
                                break
                        if codecs:
                            dct.update(parse_codecs(codecs))
            if dct.get('acodec') == 'none' or dct.get('vcodec') == 'none':
                dct['downloader_options'] = {
                    # Youtube throttles chunks >~10M
                    'http_chunk_size': 10485760,
                }
            formats.append(dct)
    else:
        manifest_url = (
            url_or_none(try_get(
                player_response,
                lambda x: x['streamingData']['hlsManifestUrl'],
                compat_str))
            or url_or_none(try_get(
                video_info, lambda x: x['hlsvp'][0], compat_str)))
        if manifest_url:
            formats = []
            m3u8_formats = self._extract_m3u8_formats(
                manifest_url, video_id, 'mp4', fatal=False)
            for a_format in m3u8_formats:
                itag = self._search_regex(
                    r'/itag/(\d+)/', a_format['url'], 'itag', default=None)
                if itag:
                    a_format['format_id'] = itag
                    if itag in self._formats:
                        dct = self._formats[itag].copy()
                        dct.update(a_format)
                        a_format = dct
                a_format['player_url'] = player_url
                # Accept-Encoding header causes failures in live streams on Youtube and Youtube Gaming
                a_format.setdefault('http_headers', {})['Youtubedl-no-compression'] = 'True'
                formats.append(a_format)
        else:
            error_message = extract_unavailable_message()
            if not error_message:
                error_message = clean_html(try_get(
                    player_response, lambda x: x['playabilityStatus']['reason'],
                    compat_str))
            if not error_message:
                error_message = clean_html(
                    try_get(video_info, lambda x: x['reason'][0], compat_str))
            if error_message:
                raise ExtractorError(error_message, expected=True)
            raise ExtractorError('no conn, hlsvp, hlsManifestUrl or url_encoded_fmt_stream_map information found in video info')

    # uploader
    video_uploader = try_get(
        video_info, lambda x: x['author'][0],
        compat_str) or str_or_none(video_details.get('author'))
    if video_uploader:
        video_uploader = compat_urllib_parse_unquote_plus(video_uploader)
    else:
        self._downloader.report_warning('unable to extract uploader name')

    # uploader_id
    video_uploader_id = None
    video_uploader_url = None
    mobj = re.search(
        r'<link itemprop="url" href="(?P<uploader_url>https?://www\.youtube\.com/(?:user|channel)/(?P<uploader_id>[^"]+))">',
        video_webpage)
    if mobj is not None:
        video_uploader_id = mobj.group('uploader_id')
        video_uploader_url = mobj.group('uploader_url')
    else:
        self._downloader.report_warning('unable to extract uploader nickname')

    channel_id = (
        str_or_none(video_details.get('channelId'))
        or self._html_search_meta(
            'channelId', video_webpage, 'channel id', default=None)
        or self._search_regex(
            r'data-channel-external-id=(["\'])(?P<id>(?:(?!\1).)+)\1',
            video_webpage, 'channel id', default=None, group='id'))
    channel_url = 'http://www.youtube.com/channel/%s' % channel_id if channel_id else None

    # thumbnail image
    # We try first to get a high quality image:
    m_thumb = re.search(r'<span itemprop="thumbnail".*?href="(.*?)">',
                        video_webpage, re.DOTALL)
    if m_thumb is not None:
        video_thumbnail = m_thumb.group(1)
    elif 'thumbnail_url' not in video_info:
        self._downloader.report_warning('unable to extract video thumbnail')
        video_thumbnail = None
    else:   # don't panic if we can't find it
        video_thumbnail = compat_urllib_parse_unquote_plus(video_info['thumbnail_url'][0])

    # upload date
    upload_date = self._html_search_meta(
        'datePublished', video_webpage, 'upload date', default=None)
    if not upload_date:
        upload_date = self._search_regex(
            [r'(?s)id="eow-date.*?>(.*?)</span>',
             r'(?:id="watch-uploader-info".*?>.*?|["\']simpleText["\']\s*:\s*["\'])(?:Published|Uploaded|Streamed live|Started) on (.+?)[<"\']'],
            video_webpage, 'upload date', default=None)
    upload_date = unified_strdate(upload_date)

    video_license = self._html_search_regex(
        r'<h4[^>]+class="title"[^>]*>\s*License\s*</h4>\s*<ul[^>]*>\s*<li>(.+?)</li',
        video_webpage, 'license', default=None)

    m_music = re.search(
        r'''(?x)
            <h4[^>]+class="title"[^>]*>\s*Music\s*</h4>\s*
            <ul[^>]*>\s*
            <li>(?P<title>.+?)
            by (?P<creator>.+?)
            (?:
                \(.+?\)|
                <a[^>]*
                    (?:
                        \bhref=["\']/red[^>]*>|             # drop possible
                        >\s*Listen ad-free with YouTube Red # YouTube Red ad
                    )
                .*?
            )?</li
        ''',
        video_webpage)
    if m_music:
        video_alt_title = remove_quotes(unescapeHTML(m_music.group('title')))
        video_creator = clean_html(m_music.group('creator'))
    else:
        video_alt_title = video_creator = None

    def extract_meta(field):
        return self._html_search_regex(
            r'<h4[^>]+class="title"[^>]*>\s*%s\s*</h4>\s*<ul[^>]*>\s*<li>(.+?)</li>\s*' % field,
            video_webpage, field, default=None)

    track = extract_meta('Song')
    artist = extract_meta('Artist')
    album = extract_meta('Album')

    # Youtube Music Auto-generated description
    release_date = release_year = None
    if video_description:
        mobj = re.search(r'(?s)Provided to YouTube by [^\n]+\n+(?P<track>[^·]+)·(?P<artist>[^\n]+)\n+(?P<album>[^\n]+)(?:.+?℗\s*(?P<release_year>\d{4})(?!\d))?(?:.+?Released on\s*:\s*(?P<release_date>\d{4}-\d{2}-\d{2}))?(.+?\nArtist\s*:\s*(?P<clean_artist>[^\n]+))?', video_description)
        if mobj:
            if not track:
                track = mobj.group('track').strip()
            if not artist:
                artist = mobj.group('clean_artist') or ', '.join(a.strip() for a in mobj.group('artist').split('·'))
            if not album:
                album = mobj.group('album'.strip())
            release_year = mobj.group('release_year')
            release_date = mobj.group('release_date')
            if release_date:
                release_date = release_date.replace('-', '')
                if not release_year:
                    release_year = int(release_date[:4])
            if release_year:
                release_year = int(release_year)

    m_episode = re.search(
        r'<div[^>]+id="watch7-headline"[^>]*>\s*<span[^>]*>.*?>(?P<series>[^<]+)</a></b>\s*S(?P<season>\d+)\s*•\s*E(?P<episode>\d+)</span>',
        video_webpage)
    if m_episode:
        series = unescapeHTML(m_episode.group('series'))
        season_number = int(m_episode.group('season'))
        episode_number = int(m_episode.group('episode'))
    else:
        series = season_number = episode_number = None

    m_cat_container = self._search_regex(
        r'(?s)<h4[^>]*>\s*Category\s*</h4>\s*<ul[^>]*>(.*?)</ul>',
        video_webpage, 'categories', default=None)
    if m_cat_container:
        category = self._html_search_regex(
            r'(?s)<a[^<]+>(.*?)</a>', m_cat_container, 'category',
            default=None)
        video_categories = None if category is None else [category]
    else:
        video_categories = None

    video_tags = [
        unescapeHTML(m.group('content'))
        for m in re.finditer(self._meta_regex('og:video:tag'), video_webpage)]

    def _extract_count(count_name):
        return str_to_int(self._search_regex(
            r'-%s-button[^>]+><span[^>]+class="yt-uix-button-content"[^>]*>([\d,]+)</span>'
            % re.escape(count_name),
            video_webpage, count_name, default=None))

    like_count = _extract_count('like')
    dislike_count = _extract_count('dislike')

    if view_count is None:
        view_count = str_to_int(self._search_regex(
            r'<[^>]+class=["\']watch-view-count[^>]+>\s*([\d,\s]+)', video_webpage,
            'view count', default=None))

    average_rating = (
        float_or_none(video_details.get('averageRating'))
        or try_get(video_info, lambda x: float_or_none(x['avg_rating'][0])))

    # subtitles
    video_subtitles = self.extract_subtitles(video_id, video_webpage)
    automatic_captions = self.extract_automatic_captions(video_id, video_webpage)

    video_duration = try_get(
        video_info, lambda x: int_or_none(x['length_seconds'][0]))
    if not video_duration:
        video_duration = int_or_none(video_details.get('lengthSeconds'))
    if not video_duration:
        video_duration = parse_duration(self._html_search_meta(
            'duration', video_webpage, 'video duration'))

    # annotations
    video_annotations = None
    if self._downloader.params.get('writeannotations', False):
        xsrf_token = self._search_regex(
            r'([\'"])XSRF_TOKEN\1\s*:\s*([\'"])(?P<xsrf_token>[A-Za-z0-9+/=]+)\2',
            video_webpage, 'xsrf token', group='xsrf_token', fatal=False)
        invideo_url = try_get(
            player_response, lambda x: x['annotations'][0]['playerAnnotationsUrlsRenderer']['invideoUrl'], compat_str)
        if xsrf_token and invideo_url:
            xsrf_field_name = self._search_regex(
                r'([\'"])XSRF_FIELD_NAME\1\s*:\s*([\'"])(?P<xsrf_field_name>\w+)\2',
                video_webpage, 'xsrf field name',
                group='xsrf_field_name', default='session_token')
            video_annotations = self._download_webpage(
                self._proto_relative_url(invideo_url),
                video_id, note='Downloading annotations',
                errnote='Unable to download video annotations', fatal=False,
                data=urlencode_postdata({xsrf_field_name: xsrf_token}))

    chapters = self._extract_chapters(video_webpage, description_original, video_id, video_duration)

    # Look for the DASH manifest
    if self._downloader.params.get('youtube_include_dash_manifest', True):
        dash_mpd_fatal = True
        for mpd_url in dash_mpds:
            dash_formats = {}
            try:
                def decrypt_sig(mobj):
                    s = mobj.group(1)
                    dec_s = self._decrypt_signature(s, video_id, player_url, age_gate)
                    return '/signature/%s' % dec_s

                mpd_url = re.sub(r'/s/([a-fA-F0-9\.]+)', decrypt_sig, mpd_url)

                for df in self._extract_mpd_formats(
                        mpd_url, video_id, fatal=dash_mpd_fatal,
                        formats_dict=self._formats):
                    if not df.get('filesize'):
                        df['filesize'] = _extract_filesize(df['url'])
                    # Do not overwrite DASH format found in some previous DASH manifest
                    if df['format_id'] not in dash_formats:
                        dash_formats[df['format_id']] = df
                    # Additional DASH manifests may end up in HTTP Error 403 therefore
                    # allow them to fail without bug report message if we already have
                    # some DASH manifest succeeded. This is temporary workaround to reduce
                    # burst of bug reports until we figure out the reason and whether it
                    # can be fixed at all.
                    dash_mpd_fatal = False
            except (ExtractorError, KeyError) as e:
                self.report_warning(
                    'Skipping DASH manifest: %r' % e, video_id)
            if dash_formats:
                # Remove the formats we found through non-DASH, they
                # contain less info and it can be wrong, because we use
                # fixed values (for example the resolution). See
                # https://github.com/ytdl-org/youtube-dl/issues/5774 for an
                # example.
                formats = [f for f in formats if f['format_id'] not in dash_formats.keys()]
                formats.extend(dash_formats.values())

    # Check for malformed aspect ratio
    stretched_m = re.search(
        r'<meta\s+property="og:video:tag".*?content="yt:stretch=(?P<w>[0-9]+):(?P<h>[0-9]+)">',
        video_webpage)
    if stretched_m:
        w = float(stretched_m.group('w'))
        h = float(stretched_m.group('h'))
        # yt:stretch may hold invalid ratio data (e.g. for Q39EVAstoRM ratio is 17:0).
        # We will only process correct ratios.
        if w > 0 and h > 0:
            ratio = w / h
            for f in formats:
                if f.get('vcodec') != 'none':
                    f['stretched_ratio'] = ratio

    if not formats:
        if 'reason' in video_info:
            if 'The uploader has not made this video available in your country.' in video_info['reason']:
                regions_allowed = self._html_search_meta(
                    'regionsAllowed', video_webpage, default=None)
                countries = regions_allowed.split(',') if regions_allowed else None
                self.raise_geo_restricted(
                    msg=video_info['reason'][0], countries=countries)
            reason = video_info['reason'][0]
            if 'Invalid parameters' in reason:
                unavailable_message = extract_unavailable_message()
                if unavailable_message:
                    reason = unavailable_message
            raise ExtractorError(
                'YouTube said: %s' % reason,
                expected=True, video_id=video_id)
        if video_info.get('license_info') or try_get(player_response, lambda x: x['streamingData']['licenseInfos']):
            raise ExtractorError('This video is DRM protected.', expected=True)

    self._sort_formats(formats)

    self.mark_watched(video_id, video_info, player_response)

    return {
        'id': video_id,
        'uploader': video_uploader,
        'uploader_id': video_uploader_id,
        'uploader_url': video_uploader_url,
        'channel_id': channel_id,
        'channel_url': channel_url,
        'upload_date': upload_date,
        'license': video_license,
        'creator': video_creator or artist,
        'title': video_title,
        'alt_title': video_alt_title or track,
        'thumbnail': video_thumbnail,
        'description': video_description,
        'categories': video_categories,
        'tags': video_tags,
        'subtitles': video_subtitles,
        'automatic_captions': automatic_captions,
        'duration': video_duration,
        'age_limit': 18 if age_gate else 0,
        'annotations': video_annotations,
        'chapters': chapters,
        'webpage_url': proto + '://www.youtube.com/watch?v=%s' % video_id,
        'view_count': view_count,
        'like_count': like_count,
        'dislike_count': dislike_count,
        'average_rating': average_rating,
        'formats': formats,
        'is_live': is_live,
        'start_time': start_time,
        'end_time': end_time,
        'series': series,
        'season_number': season_number,
        'episode_number': episode_number,
        'track': track,
        'artist': artist,
        'album': album,
        'release_date': release_date,
        'release_year': release_year,
    }

